1	//! Owner-pinned, bounded read-only acquisition of a KNB1 recovery bundle.
2	//! Successful inspection authenticates retained history, not a current output
3	//! file, durable mutation, or writer activation. No standalone fallback exists.
4	use super::{private_file, same_existing_file, sqlite_paths, Connection, Path, PathBuf};
5	use crate::{
6	    evidence_recovery_commitment::Limits,
7	    evidence_recovery_member::{Input, Membership, Object, Row},
8	    evidence_recovery_observation::Context,
9	    evidence_recovery_replay::{self as replay, Checkpoint, Replay},
10	};
11	use atproto_dasl::Cid;
12	use rusqlite::types::ValueRef;
13	use std::{
14	    sync::{
15	        atomic::{AtomicBool, Ordering},
16	        Arc,
17	    },
18	    time::{Duration, Instant},
19	};
20	
21	const SCHEMA: &str = include_str!("bundle.sql");
22	const APPLICATION_ID: i64 = 0x4b4e4231;
23	const MAX_SAFE: i64 = 9007199254740991;
24	const MAX_OBJECT: usize = 4194304;
25	
26	type Result<T> = std::result::Result<T, Error>;
27	#[derive(Debug, thiserror::Error)]
28	pub enum Error {
29	    #[error(transparent)]
30	    Store(#[from] super::Error),
31	    /// Preserve SQLite's refusal code. TooBig and DatabaseCorrupt are physical
32	    /// format refusals; READONLY_ROLLBACK (776) refuses a hot source journal.
33	    /// None is missing evidence. Busy/I/O failures remain distinct SQLite codes
34	    /// for a later owner-job capability/error mapping.
35	    #[error(transparent)]
36	    Sql(#[from] rusqlite::Error),
37	    #[error(transparent)]
38	    Io(#[from] std::io::Error),
39	    #[error("invalid recovery bundle: {0}")]
40	    Invalid(&'static str),
41	    #[error("recovery bundle acquisition budget exhausted: {0}")]
42	    Budget(&'static str),
43	    #[error("recovery bundle inspection cancelled")]
44	    Cancelled,
45	    #[error(transparent)]
46	    Replay(#[from] replay::Error),
47	}
48	/// Acquisition limits apply before Rust copies each field. Encoded bytes are
49	/// not RSS: per-row containers, one bounded SQLite row, caches and replay working
50	/// state add overhead bounded by item/cell/work limits. No universal size cap.
51	#[derive(Clone)]
52	pub struct Budget {
53	    pub items: u64,
54	    pub acquired_bytes: u64,
55	    /// Pre-open sum of the main file and existing SQLite sidecars, not a fence
56	    /// against later filesystem growth or an exact SQLite heap ceiling.
57	    pub source_bytes: u64,
58	    pub replay_items: u64,
59	    pub replay_scan_bytes: u64,
60	    /// Includes acquisition and replay; cannot preempt arbitrary filesystem I/O.
61	    pub duration: Duration,
62	    pub cancelled: Arc<AtomicBool>,
63	}
64	pub struct Inspection {
65	    source: PathBuf,
66	    replay: Replay,
67	    acquired_bytes: u64,
68	    items: u64,
69	}
70	impl Inspection {
71	    /// Routing information only; a path may change after this snapshot closes.
72	    pub fn source(&self) -> &Path {
73	        &self.source
74	    }
75	    pub fn replay(&self) -> &Replay {
76	        &self.replay
77	    }
78	    pub fn acquired_bytes(&self) -> u64 {
79	        self.acquired_bytes
80	    }
81	    pub fn items(&self) -> u64 {
82	        self.items
83	    }
84	}
85	struct Work {
86	    budget: Budget,
87	    deadline: Instant,
88	    items: u64,
89	    bytes: u64,
90	}
91	impl Work {
92	    fn check(&self) -> Result<()> {
93	        if self.budget.cancelled.load(Ordering::Relaxed) {
94	            return Err(Error::Cancelled);
95	        }
96	        if Instant::now() >= self.deadline {
97	            return Err(Error::Budget("duration"));
98	        }
99	        Ok(())
100	    }
101	    fn charge(&mut self, items: u64, bytes: usize) -> Result<()> {
102	        self.check()?;
103	        self.items = self
104	            .items
105	            .checked_add(items)
106	            .ok_or(Error::Budget("items"))?;
107	        self.bytes = self
108	            .bytes
109	            .checked_add(bytes as u64)
110	            .ok_or(Error::Budget("acquired bytes"))?;
111	        if self.items > self.budget.items {
112	            return Err(Error::Budget("items"));
113	        }
114	        if self.bytes > self.budget.acquired_bytes {
115	            return Err(Error::Budget("acquired bytes"));
116	        }
117	        Ok(())
118	    }
119	}
120	fn require(ok: bool, why: &'static str) -> Result<()> {
121	    if ok {
122	        Ok(())
123	    } else {
124	        Err(Error::Invalid(why))
125	    }
126	}
127	fn integer(row: &rusqlite::Row<'_>, col: usize, min: i64, max: i64) -> Result<u64> {
128	    match row.get_ref(col)? {
129	        ValueRef::Integer(n) if (min..=max).contains(&n) => Ok(n as u64),
130	        _ => Err(Error::Invalid("integer storage class or bounds")),
131	    }
132	}
133	// Projection triple is typeof(column), length(CAST(column AS BLOB)), bounded
134	// substr(column...). Check type and full byte length before copying the slice.
135	fn cell(
136	    row: &rusqlite::Row<'_>,
137	    col: usize,
138	    min: usize,
139	    max: usize,
140	    text: bool,
141	    work: &mut Work,
142	) -> Result<Vec<u8>> {
143	    require(
144	        row.get_ref(col)? == ValueRef::Text(if text { b"text" } else { b"blob" }),
145	        "cell storage class",
146	    )?;
147	    let len = integer(row, col + 1, min as i64, max as i64)? as usize;
148	    let bytes = match (text, row.get_ref(col + 2)?) {
149	        (true, ValueRef::Text(b)) | (false, ValueRef::Blob(b)) => b,
150	        // SQLite substr() can return NULL for an empty BLOB. The original
151	        // storage class and full byte length were checked above: this does not
152	        // reinterpret a source NULL, TEXT, or a nonempty failed projection.
153	        (false, ValueRef::Null) if len == 0 => &[],
154	        _ => return Err(Error::Invalid("projected cell storage class")),
155	    };
156	    require(bytes.len() == len, "cell truncated")?;
157	    if text {
158	        require(bytes.is_ascii() && !bytes.contains(&0), "ASCII text")?;
159	    }
160	    work.charge(0, len)?;
161	    Ok(bytes.to_vec())
162	}
163	fn cid(row: &rusqlite::Row<'_>, col: usize, work: &mut Work) -> Result<Cid> {
164	    let b = cell(row, col, 59, 59, true, work)?;
165	    let text = std::str::from_utf8(&b).map_err(|_| Error::Invalid("CID text"))?;
166	    let value: Cid = text.parse().map_err(|_| Error::Invalid("CID"))?;
167	    require(value.to_string() == text, "canonical CID spelling")?;
168	    let raw = value.to_bytes();
169	    require(
170	        raw.len() == 36 && raw[..4] == [1, 0x55, 0x12, 0x20],
171	        "raw SHA256 CID",
172	    )?;
173	    Ok(value)
174	}
175	fn projection(name: &str, max: usize) -> String {
176	    format!("typeof({name}),length(CAST({name} AS BLOB)),substr({name},1,{max})")
177	}
178	fn schema(conn: &Connection, work: &mut Work) -> Result<()> {
179	    let app: i64 = conn.query_row("PRAGMA application_id", [], |r| r.get(0))?;
180	    let version: i64 = conn.query_row("PRAGMA user_version", [], |r| r.get(0))?;
181	    let encoding: String = conn.query_row("PRAGMA encoding", [], |r| r.get(0))?;
182	    require(app == APPLICATION_ID && version == 1, "bundle profile")?;
183	    require(encoding == "UTF-8", "bundle encoding")?;
184	    let expected = Connection::open_in_memory()?;
185	    expected.execute_batch(SCHEMA)?;
186	    let query="SELECT substr(type,1,32),length(CAST(type AS BLOB)),substr(name,1,256),length(CAST(name AS BLOB)),substr(tbl_name,1,256),length(CAST(tbl_name AS BLOB)),substr(sql,1,65536),length(CAST(sql AS BLOB)) FROM sqlite_schema ORDER BY type,name";
187	    let mut actual = conn.prepare(query)?;
188	    let mut wanted = expected.prepare(query)?;
189	    let mut a = actual.query([])?;
190	    let mut e = wanted.query([])?;
191	    loop {
192	        work.check()?;
193	        match (a.next()?, e.next()?) {
194	            (None, None) => return Ok(()),
195	            (Some(a), Some(e)) => {
196	                for c in 0..8 {
197	                    require(a.get_ref(c)? == e.get_ref(c)?, "bundle schema")?;
198	                }
199	            }
200	            _ => return Err(Error::Invalid("bundle schema")),
201	        }
202	    }
203	}
204	fn identity(conn: &Connection, context: &Context, work: &mut Work) -> Result<()> {
205	    let query = format!(
206	        "SELECT singleton,{},{},profile,{},{},{} FROM bundle_identity",
207	        projection("bundle", 32),
208	        projection("observer", 80),
209	        projection("archive", 32),
210	        projection("scope", 32),
211	        projection("issuer", 80)
212	    );
213	    let mut stmt = conn.prepare(&query)?;
214	    let mut rows = stmt.query([])?;
215	    let row = rows
216	        .next()?
217	        .ok_or(Error::Invalid("missing bundle identity"))?;
218	    work.charge(1, 16)?;
219	    require(integer(row, 0, 1, 1)? == 1, "identity singleton")?;
220	    require(
221	        cell(row, 1, 32, 32, false, work)? == context.bundle,
222	        "bundle pin",
223	    )?;
224	    require(
225	        cell(row, 4, 56, 80, true, work)? == context.observer.as_bytes(),
226	        "observer pin",
227	    )?;
228	    require(
229	        integer(row, 7, 2, 3)? == context.profile as u64,
230	        "profile pin",
231	    )?;
232	    require(
233	        cell(row, 8, 32, 32, false, work)? == context.archive,
234	        "archive pin",
235	    )?;
236	    require(
237	        cell(row, 11, 32, 32, false, work)? == context.scope,
238	        "scope pin",
239	    )?;
240	    require(
241	        cell(row, 14, 56, 80, true, work)? == context.issuer.as_bytes(),
242	        "issuer pin",
243	    )?;
244	    require(rows.next()?.is_none(), "identity cardinality")
245	}
246	struct EncodedRow {
247	    sequence: u64,
248	    manifest: Vec<u8>,
