1	//! Disposable assembly over an explicit, authorized occurrence selection.
2	//! Source indices retain caller-owned occurrence/proof/snapshot lineage. This
3	//! module neither checks grants nor discovers records, and claims no completeness.
4	use crate::{
5	    evidence_capture::{Event, Observer, Outcome},
6	    evidence_reconstruction::{self as decode, Decoded, Frame},
7	};
8	use std::{
9	    collections::BTreeMap,
10	    ops::Range,
11	    sync::{
12	        atomic::{AtomicBool, Ordering},
13	        Arc,
14	    },
15	    time::{Duration, Instant},
16	};
17	
18	pub const VERSION: &str = "kan-capture-assembly/1";
19	
20	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
21	pub enum Unavailable {
22	    Missing,
23	    Corrupt,
24	    Withheld,
25	}
26	#[derive(Clone, Copy)]
27	pub enum Payload<'a> {
28	    Available(&'a [u8]),
29	    Unavailable(Unavailable),
30	}
31	/// Identity comes from verified reader selection, never from captured JSON.
32	pub struct Input<'a> {
33	    pub scope: [u8; 32],
34	    pub writer: &'a str,
35	    pub payload: Payload<'a>,
36	}
37	#[derive(Debug)]
38	pub enum Observation<'a> {
39	    Capture(Frame<'a>),
40	    Opaque,
41	    Unsupported(decode::Unsupported),
42	    Malformed(decode::Error),
43	    Unavailable(Unavailable),
44	}
45	#[derive(Clone)]
46	pub struct Limits {
47	    pub occurrences: usize,
48	    /// Raw frame bytes plus caller-supplied writer bytes, counted per occurrence.
49	    pub input_bytes: u64,
50	    /// Decode, duplicate comparison and assembled copying work; not CPU time.
51	    pub scan_bytes: u64,
52	    pub assembled_bytes: u64,
53	    pub duration: Duration,
54	    pub cancelled: Arc<AtomicBool>,
55	}
56	#[derive(Debug, thiserror::Error, PartialEq, Eq)]
57	pub enum Error {
58	    #[error("assembly budget exhausted: {0}")]
59	    Limit(&'static str),
60	    #[error("assembly cancelled")]
61	    Cancelled,
62	}
63	type Result<T> = std::result::Result<T, Error>;
64	
65	#[derive(Debug, Clone, PartialEq, Eq)]
66	pub struct SourceSpan {
67	    pub input: usize,
68	    /// Exact exclusive byte range within that input's decrypted frame.
69	    pub bytes: Range<usize>,
70	}
71	#[derive(Debug)]
72	pub struct Segment {
73	    pub offset: u64,
74	    pub length: usize,
75	    /// Exact duplicate frames share a segment, retaining every occurrence.
76	    pub sources: Vec<SourceSpan>,
77	}
78	#[derive(Debug, Clone, PartialEq, Eq)]
79	pub enum StreamIssue {
80	    OffsetOverflow { input: usize },
81	    Gap(Range<u64>),
82	    Overlap { input: usize },
83	    ConflictingExtents,
84	    BeyondExtent { input: usize },
85	    ChunkAfterEnd { input: usize },
86	    OrdinalConflict,
87	}
88	#[derive(Debug)]
89	pub struct Stream {
90	    pub segments: Vec<Segment>,
91	    /// Every request-end claim with its source. Responses have no extent claim.
92	    pub extents: Vec<(usize, u64)>,
93	    pub expected_bytes: Option<u64>,
94	    pub issues: Vec<StreamIssue>,
95	    /// A contiguous observed prefix only. Even Some(empty) is not a coverage
96	    /// certificate. None means absent data or contradictory/gapped segments.
97	    pub contiguous: Option<Vec<u8>>,
98	}
99	#[derive(Debug)]
100	pub struct Ordinal {
101	    pub value: u64,
102	    pub inputs: Vec<usize>,
103	    pub conflict: bool,
104	}
105	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
106	pub enum Terminal {
107	    Unknown,
108	    Claimed(Outcome),
109	    Conflicting,
110	}
111	#[derive(Debug)]
112	pub struct Group {
113	    pub scope: [u8; 32],
114	    pub writer: String,
115	    pub observer: Observer,
116	    pub attempt: String,
117	    pub ordinals: Vec<Ordinal>,
118	    /// Observed holes before/between ordinals; no invented trailing extent.
119	    pub ordinal_gaps: Vec<Range<u64>>,
120	    pub missing_start: bool,
121	    pub unexpected_starts: Vec<usize>,
122	    pub terminal: Terminal,
123	    pub events_after_terminal: bool,
124	    /// Observer claim only; not an exact count of lost remote records.
125	    pub unconfirmed_claim: bool,
126	    pub request: Stream,
127	    pub response: Stream,
128	}
129	#[derive(Debug)]
130	pub struct Assembly<'a> {
131	    /// Exactly one entry per input, in the same order. Keep caller lineage with it.
132	    pub observations: Vec<Observation<'a>>,
133	    pub groups: Vec<Group>,
134	    pub scanned_bytes: u64,
135	    pub assembled_bytes: u64,
136	}
137	struct Work {
138	    limits: Limits,
139	    deadline: Instant,
140	    scanned: u64,
141	    assembled: u64,
142	}
143	impl Work {
144	    fn check(&self) -> Result<()> {
145	        if self.limits.cancelled.load(Ordering::Relaxed) {
146	            return Err(Error::Cancelled);
147	        }
148	        if Instant::now() >= self.deadline {
149	            return Err(Error::Limit("duration"));
150	        }
151	        Ok(())
152	    }
153	    fn scan(&mut self, n: usize) -> Result<()> {
154	        self.check()?;
155	        self.scanned = self
156	            .scanned
157	            .checked_add(n as u64)
158	            .ok_or(Error::Limit("scan bytes"))?;
159	        if self.scanned > self.limits.scan_bytes {
160	            return Err(Error::Limit("scan bytes"));
161	        }
162	        Ok(())
163	    }
164	    fn copy(&mut self, n: usize) -> Result<()> {
165	        self.scan(n)?;
166	        self.assembled = self
167	            .assembled
168	            .checked_add(n as u64)
169	            .ok_or(Error::Limit("assembled bytes"))?;
170	        if self.assembled > self.limits.assembled_bytes {
171	            return Err(Error::Limit("assembled bytes"));
172	        }
173	        Ok(())
174	    }
175	}
176	fn frame<'s, 'a>(observations: &'s [Observation<'a>], i: usize) -> &'s Frame<'a> {
177	    match &observations[i] {
178	        Observation::Capture(f) => f,
179	        _ => unreachable!(),
180	    }
181	}
182	fn raw<'a>(input: &Input<'a>) -> &'a [u8] {
183	    match input.payload {
184	        Payload::Available(b) => b,
185	        _ => unreachable!(),
186	    }
187	}
188	fn identical(a: &[u8], b: &[u8], work: &mut Work) -> Result<bool> {
189	    if a.len() != b.len() {
190	        work.check()?;
191	        return Ok(false);
192	    }
193	    for (a, b) in a.chunks(65536).zip(b.chunks(65536)) {
194	        work.scan(a.len())?;
195	        if a != b {
196	            return Ok(false);
197	        }
198	    }
199	    Ok(true)
200	}
201	fn stream(
202	    ordinals: &[Ordinal],
203	    observations: &[Observation<'_>],
204	    request: bool,
205	    work: &mut Work,
206	) -> Result<Stream> {
207	    let mut out = Stream {
208	        segments: vec![],
209	        extents: vec![],
210	        expected_bytes: None,
211	        issues: vec![],
212	        contiguous: None,
213	    };
214	    for ordinal in ordinals {
215	        work.check()?;
216	        if ordinal.conflict {
217	            out.issues.push(StreamIssue::OrdinalConflict);
218	        }
219	        // Conflicting variants remain separate. Identical duplicates share only
220	        // their interpretation, never their occurrence identity.
221	        let variants = if ordinal.conflict {
222	            ordinal.inputs.as_slice()
223	        } else {
224	            &ordinal.inputs[..1]
225	        };
226	        for &i in variants {
227	            let f = frame(observations, i);
228	            if request {
229	                if let Event::RequestEnd { bytes } = f.header.event {
230	                    for &index in if ordinal.conflict {
231	                        std::slice::from_ref(&i)
232	                    } else {
233	                        &ordinal.inputs
234	                    } {
235	                        out.extents.push((index, bytes));
236	                    }
237	                }
238	            }
239	            let offset = match (&f.header.event, request) {
240	                (Event::RequestChunk { offset }, true)
241	                | (Event::ResponseChunk { offset }, false) => *offset,
242	                _ => continue,
243	            };
244	            let sources = if ordinal.conflict {
245	                std::slice::from_ref(&i)
246	            } else {
247	                &ordinal.inputs
248	            };
249	            out.segments.push(Segment {
250	                offset,
251	                length: f.body.len(),
252	                sources: sources
253	                    .iter()
254	                    .map(|&input| SourceSpan {
255	                        input,
256	                        bytes: frame(observations, input).body_span.clone(),
257	                    })
258	                    .collect(),
259	            });
260	        }
261	    }
262	    if let Some(&(_, n)) = out.extents.first() {
263	        if out.extents.iter().all(|&(_, x)| x == n) {
264	            out.expected_bytes = Some(n);
265	        } else {
266	            out.issues.push(StreamIssue::ConflictingExtents);
267	        }
268	    }
269	    out.segments.sort_by_key(|s| (s.offset, s.sources[0].input));
270	    work.check()?;
271	    let mut end = 0;
272	    let mut total = 0usize;
273	    let first_end = out
274	        .extents
275	        .iter()
276	        .map(|&(i, _)| frame(observations, i).header.ordinal)
277	        .min();
278	    for s in &out.segments {
279	        work.check()?;
280	        let input = s.sources[0].input;
281	        if first_end.is_some_and(|n| n < frame(observations, input).header.ordinal) {
282	            out.issues.push(StreamIssue::ChunkAfterEnd { input });
283	        }
284	        let Some(next) = s.offset.checked_add(s.length as u64) else {
285	            out.issues.push(StreamIssue::OffsetOverflow { input });
286	            continue;
287	        };
288	        if s.offset > end {
289	            out.issues.push(StreamIssue::Gap(end..s.offset));
290	        }
291	        // Empty frames at a covered offset contain no overlapping byte evidence.
292	        if s.length > 0 && s.offset < end {
293	            out.issues.push(StreamIssue::Overlap { input });
294	        }
295	        if out.expected_bytes.is_some_and(|extent| next > extent) {
296	            out.issues.push(StreamIssue::BeyondExtent { input });
297	        }
298	        end = end.max(next);
299	        total = total
300	            .checked_add(s.length)
301	            .ok_or(Error::Limit("assembled bytes"))?;
302	    }
303	    if let Some(n) = out.expected_bytes {
304	        if end < n {
305	            out.issues.push(StreamIssue::Gap(end..n));
306	        }
307	    }
308	    if out.issues.is_empty() && (!out.segments.is_empty() || out.expected_bytes == Some(0)) {
309	        work.copy(total)?;
310	        let mut bytes = Vec::with_capacity(total);
311	        for s in &out.segments {
312	            work.check()?;
313	            bytes.extend_from_slice(frame(observations, s.sources[0].input).body);
314	        }
315	        out.contiguous = Some(bytes);
316	    }
317	    Ok(out)
318	}
319	
320	/// Assemble the explicit selection or refuse the whole operation on a budget.
321	/// No serializer is provided: API consumers must preserve u64 coordinates.
322	pub fn assemble<'a>(inputs: &[Input<'a>], limits: Limits) -> Result<Assembly<'a>> {
323	    assemble_observed(inputs, limits, || {})
324	}
325	fn assemble_observed<'a>(
326	    inputs: &[Input<'a>],
327	    limits: Limits,
328	    mut after_decode: impl FnMut(),
329	) -> Result<Assembly<'a>> {
330	    if limits.duration.is_zero() || limits.duration > Duration::from_secs(3600) {
331	        return Err(Error::Limit("duration"));
332	    }
333	    let deadline = Instant::now()
334	        .checked_add(limits.duration)
335	        .ok_or(Error::Limit("duration"))?;
336	    let mut work = Work {
337	        limits,
338	        deadline,
339	        scanned: 0,
340	        assembled: 0,
341	    };
342	    work.check()?;
343	    if inputs.len() > work.limits.occurrences {
344	        return Err(Error::Limit("occurrences"));
345	    }
346	    let mut input_bytes = 0u64;
347	    // Preflight every encoded input before decoding/allocating derived state.
348	    for input in inputs {
349	        work.check()?;
350	        let bytes = match input.payload {
351	            Payload::Available(b) => b.len(),
352	            _ => 0,
353	        };
354	        input_bytes = input_bytes
355	            .checked_add(bytes as u64)
356	            .and_then(|n| n.checked_add(input.writer.len() as u64))
357	            .ok_or(Error::Limit("input bytes"))?;
358	        if input_bytes > work.limits.input_bytes {
359	            return Err(Error::Limit("input bytes"));
360	        }
361	    }
362	    let mut observations = Vec::with_capacity(inputs.len());
363	    for input in inputs {
364	        work.check()?;
365	        observations.push(match input.payload {
366	            Payload::Unavailable(reason) => Observation::Unavailable(reason),
367	            Payload::Available(bytes) => {
368	                work.scan(bytes.len())?;
369	                match decode::decode(bytes) {
370	                    Ok(Decoded::Capture(f)) => Observation::Capture(f),
371	                    Ok(Decoded::Opaque) => Observation::Opaque,
372	                    Ok(Decoded::Unsupported(r)) => Observation::Unsupported(r),
373	                    Err(e) => Observation::Malformed(e),
374	                }
375	            }
376	        });
377	        after_decode();
378	    }
379	    type Key<'a> = ([u8; 32], &'a str, u8, &'a str);
380	    let mut grouped: BTreeMap<Key<'_>, BTreeMap<u64, Vec<usize>>> = BTreeMap::new();
381	    for (i, observation) in observations.iter().enumerate() {
382	        work.check()?;
383	        if let Observation::Capture(f) = observation {
384	            let observer = match f.header.observer {
385	                Observer::Collector => 0,
386	                Observer::Gateway => 1,
387	            };
388	            grouped
389	                .entry((
390	                    inputs[i].scope,
391	                    inputs[i].writer,
392	                    observer,
393	                    &f.header.attempt,
394	                ))
395	                .or_default()
396	                .entry(f.header.ordinal)
397	                .or_default()
398	                .push(i);
399	        }
400	    }
401	    let mut groups = Vec::with_capacity(grouped.len());
402	    for ((scope, writer, observer, attempt), ordered) in grouped {
403	        let mut ordinals = Vec::with_capacity(ordered.len());
404	        let mut gaps = vec![];
405	        let mut next = Some(0);
406	        let mut starts = vec![];
407	        let mut terminals = vec![];
408	        let mut unconfirmed = false;
409	        for (value, indices) in ordered {
410	            work.check()?;
411	            if let Some(n) = next {
412	                if value > n {
413	                    gaps.push(n..value);
414	                }
415	            }
416	            next = value.checked_add(1);
417	            let mut conflict = false;
418	            for &i in &indices[1..] {
419	                if !identical(raw(&inputs[indices[0]]), raw(&inputs[i]), &mut work)? {
420	                    conflict = true;
421	                }
422	            }
423	            for &i in &indices {
424	                let f = frame(&observations, i);
425	                unconfirmed |= f.header.unconfirmed_before > 0;
426	            }
427	            let variants = if conflict {
428	                indices.as_slice()
429	            } else {
430	                &indices[..1]
431	            };
432	            for &i in variants {
433	                match frame(&observations, i).header.event {
434	                    Event::Started { .. } => starts.push(i),
435	                    Event::Terminal { outcome } => terminals.push((value, outcome)),
436	                    _ => {}
437	                }
438	            }
439	            ordinals.push(Ordinal {
440	                value,
441	                inputs: indices,
442	                conflict,
443	            });
444	        }
445	        let missing_start = !starts
446	            .iter()
447	            .any(|&i| frame(&observations, i).header.ordinal == 0);
448	        let unexpected_starts = starts
449	            .into_iter()
450	            .filter(|&i| frame(&observations, i).header.ordinal != 0)
451	            .collect();
452	        let terminal = match terminals.as_slice() {
453	            [] => Terminal::Unknown,
454	            [(n, outcome)] if !ordinals.iter().any(|o| o.value == *n && o.conflict) => {
455	                Terminal::Claimed(*outcome)
456	            }
457	            _ => Terminal::Conflicting,
458	        };
459	        let events_after_terminal = terminals
460	            .first()
461	            .is_some_and(|(n, _)| ordinals.last().is_some_and(|o| o.value > *n));
462	        let request = stream(&ordinals, &observations, true, &mut work)?;
463	        let response = stream(&ordinals, &observations, false, &mut work)?;
464	        groups.push(Group {
465	            scope,
466	            writer: writer.into(),
467	            observer: if observer == 0 {
468	                Observer::Collector
469	            } else {
470	                Observer::Gateway
471	            },
472	            attempt: attempt.into(),
473	            ordinals,
474	            ordinal_gaps: gaps,
475	            missing_start,
476	            unexpected_starts,
477	            terminal,
478	            events_after_terminal,
479	            unconfirmed_claim: unconfirmed,
480	            request,
481	            response,
482	        });
483	    }
484	    work.check()?;
485	    Ok(Assembly {
486	        observations,
487	        groups,
488	        scanned_bytes: work.scanned,
489	        assembled_bytes: work.assembled,
490	    })
491	}
492	
493	#[cfg(test)]
494	mod tests {
495	    use super::*;
496	    #[test]
497	    fn cancellation_after_decode_stops_before_the_next_input() {
498	        let cancelled = Arc::new(AtomicBool::new(false));
499	        let limits = Limits {
500	            occurrences: 10,
501	            input_bytes: 100,
502	            scan_bytes: 100,
503	            assembled_bytes: 100,
504	            duration: Duration::from_secs(10),
505	            cancelled: cancelled.clone(),
506	        };
507	        let inputs = [
508	            Input {
509	                scope: [0; 32],
510	                writer: "w",
511	                payload: Payload::Available(b"opaque"),
512	            },
513	            Input {
514	                scope: [0; 32],
515	                writer: "w",
516	                payload: Payload::Available(b"second"),
517	            },
518	        ];
519	        let mut decoded = 0;
520	        let result = assemble_observed(&inputs, limits, || {
521	            decoded += 1;
522	            cancelled.store(true, Ordering::Relaxed);
523	        });
524	        assert_eq!(result.unwrap_err(), Error::Cancelled);
525	        assert_eq!(decoded, 1);
526	    }
527	}
