#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Header {
    let length: [u8; 4] = bytes.get(5..9).ok_or(Error::Envelope)?.try_into().unwrap();
    let length = u32::from_be_bytes(length) as usize;
    if length > MAX_HEADER {
        return Err(Error::Limit);
    }
    let end = 9usize.checked_add(length).ok_or(Error::Envelope)?;
    let json = bytes.get(9..end).ok_or(Error::Envelope)?;
    let body = &bytes[end..];
    if body.len() > CHUNK {
        return Err(Error::Limit);
    }
    let Unique(value) = serde_json::from_slice(json).map_err(|_| Error::Header)?;
    let object = value.as_object().ok_or(Error::Header)?;
    let version = object
        .get("version")
        .and_then(Value::as_u64)
        .ok_or(Error::Header)?;
    if version != 2 {
        return Ok(Decoded::Unsupported(Unsupported::Version));
    }
    let observer = object
        .get("observer")
        .and_then(Value::as_str)
        .ok_or(Error::Header)?;
    if !matches!(observer, "collector" | "gateway") {
        return Ok(Decoded::Unsupported(Unsupported::Observer));
    }
    let event = object
        .get("event")
        .and_then(Value::as_object)
        .ok_or(Error::Header)?;
    let kind = event
        .get("type")
        .and_then(Value::as_str)
        .ok_or(Error::Header)?;
    if !matches!(
        kind,
        "started"
            | "request-chunk"
            | "request-end"
            | "forwarding-intent"
            | "transport-link"
            | "http-metadata-chunk"
            | "http-metadata"
            | "response-head"
            | "response-chunk"
            | "terminal"
    ) {
        return Ok(Decoded::Unsupported(Unsupported::Event));
    }
    if kind == "terminal" {
        let outcome = event
            .get("outcome")
            .and_then(Value::as_str)
            .ok_or(Error::Header)?;
        if !matches!(outcome, "completed" | "outcome-unknown") {
            return Ok(Decoded::Unsupported(Unsupported::Outcome));
        }
    }
    // An absent clock claim is not the explicit null emitted by the recorder.
    if !object.contains_key("observed_at_unix_micros") {
        return Err(Error::Header);
    }
    // Serde's internally tagged unit variant accepts extra map entries even
    // with deny_unknown_fields. Do not silently discard fields from a recognized
    // forwarding intent; the struct variants retain their derived strict checks.
    if kind == "forwarding-intent" && event.len() != 1 {
        return Err(Error::Header);
    }
    let header: Header = serde_json::from_value(value).map_err(|_| Error::Header)?;
    if !identifier(&header.attempt)
        || matches!(&header.event, Event::TransportLink { exchange } if !identifier(exchange))
        || matches!(&header.event, Event::Started { method, route } if method.len()>32 || route.len()>2048)
    {
        return Err(Error::Header);
    }
    if !body.is_empty()
        && !matches!(
            header.event,
            Event::RequestChunk { .. }
                | Event::ResponseChunk { .. }
                | Event::HttpMetadataChunk { .. }
        )
    {
        return Err(Error::Body);
    }
    Ok(Decoded::Capture(Frame {
        header,
        body,
        header_span: 9..end,
        body_span: end..bytes.len(),
    }))
}

