    // all-overlap worst case: issues bounded linearly
    let same: Vec<Vec<u8>> = (0..5000u64).map(|i| rq(i, 0, b"abc")).collect();
    let inputs: Vec<_> = same.iter().map(|f| inp(f, 1, "w")).collect();
